    "unitId": "n2:integrated-comprehension:2014-12:1:line-1",
    "text": "うーん、そうですね。このあたりのドライブコースとしては、四つございます。まず、海岸コースですが、こちらは海が見渡せますし、途中に花の公園があって、季節の花を楽しむことができる人気のコースですよ。ただ、今日は休日だから、込んでますね。",
