    "unitId": "n2:integrated-comprehension:2014-12:1:line-7",
    "text": "海は見えないんですが、お勧めのコースがありますよ。山の麓コースで、山の上の方には行きませんが、混雑もなく快適ですし、今は菜の花畑が続いていてきれいですよ。それに途中に有名な神社もあります。",
