    "text": "うーん。そうですね。お墓参りへ行くお客さんの送迎をすることがあるんですが、お墓参りをされるお客さんはお墓の掃除をすることが多いんです。高齢の方も多いので、送迎とお墓の掃除の手伝いをセットにしてみてはどうでしょうか。",
